    let id: String
    let sender: String
    let subject: String
    let preview: String
    let receivedAt: Date
    let isRead: Bool
    let bodyHtml: String?
}

struct CaptchaChallenge: Identifiable {
    let id: String
    let imageData: Data
    let timestamp: Date
